"""Answer comparison.

Most problems have a single right answer and use ``exact``. Problems that
accept any of several valid answers (unordered output, multiple valid
topological orders, ties) name a comparator or a custom checker instead.

Every checker has the signature ``fn(actual, case, passed_args) -> (ok, note)``
where ``case`` is the declarative :class:`~dsa.models.T` (so the pristine input
can be rebuilt) and ``passed_args`` are the live objects the solution received.
"""

from __future__ import annotations

from typing import Any

from .models import GRAPH, LL, RLIST, TREE
from .structures import (
    build_graph,
    build_random_list,
    graph_to_adjacency,
    random_list_to_pairs,
)

TOLERANCE = 1e-4


# --------------------------------------------------------------------------
# generic comparators
# --------------------------------------------------------------------------


def _key(value: Any) -> tuple:
    """Sort key that tolerates mixed types inside nested lists."""
    if isinstance(value, (list, tuple)):
        return (2, tuple(_key(v) for v in value))
    if value is None:
        return (0, ())
    if isinstance(value, bool):
        return (1, (0, float(value)))
    if isinstance(value, (int, float)):
        return (1, (0, float(value)))
    return (1, (1, str(value)))


def _canon_sorted(value: Any) -> Any:
    if isinstance(value, (list, tuple)):
        return sorted(value, key=_key)
    return value


def _canon_nested(value: Any) -> Any:
    """Sort inner sequences and then the outer one: order-insensitive both ways."""
    if not isinstance(value, (list, tuple)):
        return value
    inner = [
        sorted(v, key=_key) if isinstance(v, (list, tuple)) else v for v in value
    ]
    return sorted(inner, key=_key)


def _approx_equal(expected: Any, actual: Any) -> bool:
    if isinstance(expected, (list, tuple)):
        if not isinstance(actual, (list, tuple)) or len(expected) != len(actual):
            return False
        return all(_approx_equal(e, a) for e, a in zip(expected, actual))
    if isinstance(expected, bool) or isinstance(actual, bool):
        return expected == actual
    if isinstance(expected, (int, float)) and isinstance(actual, (int, float)):
        return abs(expected - actual) <= TOLERANCE
    return expected == actual


def _normalize_bools(value: Any) -> Any:
    """1 == True in Python, but a solution returning 1 for a bool answer is fine."""
    if isinstance(value, list):
        return [_normalize_bools(v) for v in value]
    if isinstance(value, bool):
        return value
    return value


def exact(actual: Any, case: Any, passed_args: Any) -> tuple[bool, str]:
    return _normalize_bools(actual) == _normalize_bools(case.expect), ""


def unordered(actual: Any, case: Any, passed_args: Any) -> tuple[bool, str]:
    if not isinstance(actual, (list, tuple)):
        return False, "expected a list"
    return _canon_sorted(actual) == _canon_sorted(case.expect), "compared as a multiset"


def nested_set(actual: Any, case: Any, passed_args: Any) -> tuple[bool, str]:
    if not isinstance(actual, (list, tuple)):
        return False, "expected a list of lists"
    ok = _canon_nested(actual) == _canon_nested(case.expect)
    return ok, "inner and outer order ignored"


def approx(actual: Any, case: Any, passed_args: Any) -> tuple[bool, str]:
    return _approx_equal(case.expect, actual), f"tolerance {TOLERANCE}"


# --------------------------------------------------------------------------
# problem-specific checkers
# --------------------------------------------------------------------------


def clone_graph(actual: Any, case: Any, passed_args: Any) -> tuple[bool, str]:
    """Must be structurally identical to the input and share no nodes with it."""
    marker = case.args[0]
    original = marker.adjacency if isinstance(marker, GRAPH) else ()
    if not original:
        return actual is None, "empty graph must clone to None"
    if actual is None:
        return False, "returned None for a non-empty graph"

    if graph_to_adjacency(actual) != [list(row) for row in original]:
        return False, "clone has a different shape than the input"

    originals = {id(n) for n in _reachable(passed_args[0])}
    for node in _reachable(actual):
        if id(node) in originals:
            return False, f"node {node.val} is the original object, not a copy"
    return True, "deep copy verified"


def _reachable(node: Any) -> list:
    if node is None:
        return []
    seen: dict[int, Any] = {}
    stack = [node]
    while stack:
        cur = stack.pop()
        if id(cur) in seen:
            continue
        seen[id(cur)] = cur
        stack.extend(cur.neighbors)
    return list(seen.values())


def copy_random_list(actual: Any, case: Any, passed_args: Any) -> tuple[bool, str]:
    """Must reproduce the val/random layout with entirely fresh nodes."""
    marker = case.args[0]
    pairs = [list(p) for p in marker.pairs] if isinstance(marker, RLIST) else []
    if not pairs:
        return actual is None, "empty list must copy to None"
    if random_list_to_pairs(actual) != pairs:
        return False, "copy has different values or random pointers"

    originals = set()
    cur = passed_args[0]
    while cur is not None:
        originals.add(id(cur))
        cur = cur.next
    cur = actual
    while cur is not None:
        if id(cur) in originals:
            return False, f"node {cur.val} is the original object, not a copy"
        cur = cur.next
    return True, "deep copy verified"


def topological_order(actual: Any, case: Any, passed_args: Any) -> tuple[bool, str]:
    """Any ordering that respects every ``[course, prerequisite]`` edge."""
    n, prerequisites = case.args[0], case.args[1]
    expected = case.expect
    if expected == []:
        return actual == [], "a cycle means no valid ordering exists"
    if not isinstance(actual, (list, tuple)) or sorted(actual) != list(range(n)):
        return False, f"must be a permutation of 0..{n - 1}"
    position = {course: i for i, course in enumerate(actual)}
    for course, prereq in prerequisites:
        if position[prereq] > position[course]:
            return False, f"course {prereq} must come before {course}"
    return True, "valid topological order"


def alien_order(actual: Any, case: Any, passed_args: Any) -> tuple[bool, str]:
    """Any letter ordering consistent with the dictionary; "" when impossible."""
    words = [str(w) for w in case.args[0]]
    if case.expect == "":
        return actual == "", "this dictionary is inconsistent"
    if not isinstance(actual, str):
        return False, "expected a string"

    letters = {ch for word in words for ch in word}
    if sorted(actual) != sorted(letters):
        return False, "must contain each distinct letter exactly once"

    position = {ch: i for i, ch in enumerate(actual)}
    for first, second in zip(words, words[1:]):
        for a, b in zip(first, second):
            if a != b:
                if position[a] > position[b]:
                    return False, f"'{a}' must come before '{b}'"
                break
        else:
            if len(first) > len(second):
                return False, "a prefix must not follow its longer word"
    return True, "valid alien ordering"


def any_longest_palindrome(actual: Any, case: Any, passed_args: Any) -> tuple[bool, str]:
    """Any substring that is a palindrome of the optimal length."""
    source, expected = str(case.args[0]), str(case.expect)
    if not isinstance(actual, str):
        return False, "expected a string"
    if len(actual) != len(expected):
        return False, f"longest palindrome has length {len(expected)}"
    if actual != actual[::-1]:
        return False, "not a palindrome"
    if actual not in source:
        return False, "not a substring of the input"
    return True, "any palindrome of optimal length is accepted"


def any_k_closest(actual: Any, case: Any, passed_args: Any) -> tuple[bool, str]:
    """Ties may be broken either way, so compare the multiset of distances."""
    points, k = case.args[0], case.args[1]
    if not isinstance(actual, (list, tuple)) or len(actual) != k:
        return False, f"expected {k} points"
    allowed = [list(p) for p in points]
    for point in actual:
        if list(point) not in allowed:
            return False, f"{list(point)} is not one of the input points"
        allowed.remove(list(point))

    def dist(p: Any) -> int:
        return p[0] * p[0] + p[1] * p[1]

    best = sorted(dist(p) for p in points)[:k]
    if sorted(dist(p) for p in actual) != best:
        return False, "these are not the k closest points"
    return True, "ties may be broken either way"


CHECKERS = {
    "exact": exact,
    "unordered": unordered,
    "nested_set": nested_set,
    "approx": approx,
    "clone_graph": clone_graph,
    "copy_random_list": copy_random_list,
    "topological_order": topological_order,
    "alien_order": alien_order,
    "any_longest_palindrome": any_longest_palindrome,
    "any_k_closest": any_k_closest,
}


def compare(name: str, actual: Any, case: Any, passed_args: Any) -> tuple[bool, str]:
    checker = CHECKERS.get(name)
    if checker is None:
        raise KeyError(f"unknown comparator {name!r}")
    return checker(actual, case, passed_args)

