"""The problem catalogue: the NeetCode 150, in roadmap order."""

from __future__ import annotations

import importlib
import re
from functools import lru_cache
from typing import Iterable

from .models import Problem

#: category modules in NeetCode roadmap order (a sensible study order, since
#: later categories build on the patterns in earlier ones)
CATEGORY_MODULES: tuple[str, ...] = (
    "arrays_hashing",
    "two_pointers",
    "sliding_window",
    "stack",
    "binary_search",
    "linked_list",
    "trees",
    "tries",
    "heap",
    "backtracking",
    "graphs",
    "advanced_graphs",
    "dp_1d",
    "dp_2d",
    "greedy",
    "intervals",
    "math_geometry",
    "bit_manipulation",
)

DIFFICULTY_ORDER = {"Easy": 0, "Medium": 1, "Hard": 2}


@lru_cache(maxsize=1)
def all_problems() -> tuple[Problem, ...]:
    """Every problem, numbered 1..150 in roadmap order."""
    from dataclasses import replace

    collected: list[Problem] = []
    for module_name in CATEGORY_MODULES:
        module = importlib.import_module(f"dsa.problems.{module_name}")
        for item in module.PROBLEMS:
            collected.append(replace(item, number=len(collected) + 1))
    return tuple(collected)


@lru_cache(maxsize=1)
def _by_slug() -> dict[str, Problem]:
    return {p.slug: p for p in all_problems()}


@lru_cache(maxsize=1)
def categories() -> tuple[str, ...]:
    seen: list[str] = []
    for problem in all_problems():
        if problem.category not in seen:
            seen.append(problem.category)
    return tuple(seen)


def in_category(category: str) -> tuple[Problem, ...]:
    return tuple(p for p in all_problems() if p.category == category)


def get_problem(reference: str) -> Problem:
    """Look a problem up by slug, roadmap number, or title fragment.

    Raises :class:`LookupError` with suggestions when the reference is
    ambiguous or unknown.
    """
    reference = reference.strip()
    table = _by_slug()
    if reference in table:
        return table[reference]

    if reference.isdigit():
        number = int(reference)
        problems = all_problems()
        if 1 <= number <= len(problems):
            return problems[number - 1]
        raise LookupError(f"there is no problem #{number} (the roadmap has {len(problems)})")

    matches = search(reference)
    if len(matches) == 1:
        return matches[0]
    if not matches:
        raise LookupError(f"no problem matches {reference!r} — try `dsa list`")
    names = ", ".join(m.slug for m in matches[:8])
    raise LookupError(f"{reference!r} is ambiguous — did you mean: {names}?")


def search(query: str) -> tuple[Problem, ...]:
    """Case-insensitive match against slug and title."""
    needle = re.sub(r"[^a-z0-9]+", "", query.lower())
    if not needle:
        return ()
    hits = []
    for problem in all_problems():
        haystacks = (
            re.sub(r"[^a-z0-9]+", "", problem.slug.lower()),
            re.sub(r"[^a-z0-9]+", "", problem.title.lower()),
        )
        if any(needle in hay for hay in haystacks):
            hits.append(problem)
    return tuple(hits)


def filter_problems(
    problems: Iterable[Problem] | None = None,
    category: str | None = None,
    difficulty: str | None = None,
    query: str | None = None,
) -> tuple[Problem, ...]:
    """Apply the common list filters. Category and difficulty accept prefixes."""
    items = tuple(problems) if problems is not None else all_problems()
    if category:
        needle = category.lower()
        items = tuple(
            p
            for p in items
            if needle in p.category.lower() or needle in _slugify(p.category)
        )
    if difficulty:
        needle = difficulty.lower()
        items = tuple(p for p in items if p.difficulty.lower().startswith(needle))
    if query:
        allowed = {p.slug for p in search(query)}
        items = tuple(p for p in items if p.slug in allowed)
    return items


def _slugify(text: str) -> str:
    return re.sub(r"[^a-z0-9]+", "-", text.lower()).strip("-")


def category_slug(category: str) -> str:
    return _slugify(category)


def resolve_category(reference: str) -> str | None:
    """Map a user-supplied category name or slug to the canonical category."""
    needle = reference.lower().strip()
    for category in categories():
        if needle == category.lower() or needle == _slugify(category):
            return category
    for category in categories():
        if needle in category.lower() or needle in _slugify(category):
            return category
    return None

