"""Test executor. Runs in a separate process so that a runaway loop, a crash,
or a blown recursion limit in a solution cannot take the CLI down with it.

Protocol: a JSON payload on stdin, a JSON report written to ``report_path``.
Only plain values ever cross the process boundary — comparison happens here,
where the live objects are.
"""

from __future__ import annotations

import contextlib
import importlib.util
import io
import json
import os
import sys
import threading
import time
import traceback
from dataclasses import replace
from typing import Any

from .checkers import compare
from .models import ANY, GRAPH, LL, PICK, RLIST, TREE, R, T, _Any
from .registry import get_problem
from .structures import (
    build_graph,
    build_list,
    build_random_list,
    build_tree,
    graph_to_adjacency,
    list_to_values,
    random_list_to_pairs,
    tree_to_values,
)

#: comparators that inspect the live returned objects instead of plain values
RAW_CHECKERS = {"clone_graph", "copy_random_list"}

RECURSION_LIMIT = 60_000
STACK_BYTES = 256 * 1024 * 1024


# --------------------------------------------------------------------------
# markers <-> live objects
# --------------------------------------------------------------------------


def materialize(value: Any, results: list | None = None) -> Any:
    """Turn declarative test data into the live objects a solution expects."""
    if isinstance(value, LL):
        return build_list(list(value.values), value.cycle)
    if isinstance(value, TREE):
        return build_tree(list(value.values))
    if isinstance(value, GRAPH):
        return build_graph([list(row) for row in value.adjacency])
    if isinstance(value, RLIST):
        return build_random_list([list(p) for p in value.pairs])
    if isinstance(value, R):
        if results is None:
            raise ValueError("R(...) is only valid inside class operations")
        return results[value.index]
    if isinstance(value, (list, tuple)):
        return [materialize(v, results) for v in value]
    return value


def resolve_picks(value: Any, built: list) -> Any:
    """Second materialization pass: swap PICK markers for real nodes.

    Runs after the arguments exist, because a PICK must point at a node *inside*
    one of them rather than at an equal-valued copy.
    """
    if isinstance(value, PICK):
        found = _find_node(built[value.arg], value.value)
        if found is None:
            raise ValueError(f"no node with value {value.value!r} in argument {value.arg}")
        return found
    if isinstance(value, list):
        return [resolve_picks(v, built) for v in value]
    return value


def _find_node(root: Any, target: Any) -> Any:
    """Breadth-first search for a node by value in a binary tree."""
    queue = [root]
    while queue:
        node = queue.pop(0)
        if node is None:
            continue
        if node.val == target:
            return node
        queue.append(node.left)
        queue.append(node.right)
    return None


def plain(value: Any) -> Any:
    """Strip markers down to the plain values they stand for."""
    if isinstance(value, PICK):
        return value.value
    if isinstance(value, LL):
        return list(value.values) if value.values else None
    if isinstance(value, TREE):
        return list(value.values) if value.values else None
    if isinstance(value, GRAPH):
        return [list(row) for row in value.adjacency]
    if isinstance(value, RLIST):
        return [list(p) for p in value.pairs]
    if isinstance(value, (list, tuple)):
        return [plain(v) for v in value]
    return value


def normalize(actual: Any, expect: Any) -> Any:
    """Serialize a returned structure into plain values, guided by ``expect``."""
    if isinstance(expect, LL):
        return list_to_values(actual)
    if isinstance(expect, TREE):
        return tree_to_values(actual)
    if isinstance(expect, GRAPH):
        return graph_to_adjacency(actual)
    if isinstance(expect, RLIST):
        return random_list_to_pairs(actual)
    if isinstance(expect, (list, tuple)) and any(
        isinstance(e, (LL, TREE, GRAPH, RLIST)) for e in expect
    ):
        if not isinstance(actual, (list, tuple)):
            return actual
        return [
            normalize(a, e)
            for a, e in zip(actual, list(expect) + [None] * len(actual))
        ]
    return _to_lists(actual)


def _to_lists(value: Any) -> Any:
    """Tuples and other sequences compare equal to the list forms we expect."""
    if isinstance(value, tuple):
        return [_to_lists(v) for v in value]
    if isinstance(value, list):
        return [_to_lists(v) for v in value]
    if isinstance(value, (set, frozenset)):
        return sorted(_to_lists(v) for v in value)
    return value


def preview(value: Any, limit: int = 220) -> str:
    """Short, readable rendering of a value for the results table."""
    try:
        text = json.dumps(value, default=str)
    except (TypeError, ValueError):
        text = repr(value)
    if len(text) > limit:
        text = text[: limit - 3] + "..."
    return text


# --------------------------------------------------------------------------
# execution
# --------------------------------------------------------------------------


def load_solution(path: str) -> Any:
    """Import the user's solution file as a module."""
    spec = importlib.util.spec_from_file_location("user_solution", path)
    if spec is None or spec.loader is None:
        raise ImportError(f"cannot import {path}")
    module = importlib.util.module_from_spec(spec)
    sys.modules["user_solution"] = module
    spec.loader.exec_module(module)
    return module


def _format_error(exc: BaseException) -> str:
    """Traceback trimmed to the frames inside the user's file."""
    frames = traceback.extract_tb(exc.__traceback__)
    user_frames = [f for f in frames if "user_solution" in (f.filename or "")]
    lines = []
    for frame in user_frames or frames[-2:]:
        lines.append(f"  line {frame.lineno}: {(frame.line or '').strip()}")
    detail = "\n".join(lines)
    head = f"{type(exc).__name__}: {exc}"
    return f"{head}\n{detail}" if detail else head


def run_function_case(problem: Any, fn: Any, case: T) -> dict:
    """Call a plain function once and compare its answer."""
    passed = materialize(case.args)
    passed = [resolve_picks(arg, passed) for arg in passed]
    started = time.perf_counter()
    returned = fn(*passed)
    elapsed = (time.perf_counter() - started) * 1000

    if problem.mutates is not None:
        returned = passed[problem.mutates]

    if problem.compare in RAW_CHECKERS:
        ok, note = compare(problem.compare, returned, case, passed)
        shown = preview(normalize(returned, case.expect))
    else:
        actual = normalize(returned, case.expect)
        plain_case = replace(case, expect=plain(case.expect))
        ok, note = compare(problem.compare, actual, plain_case, passed)
        shown = preview(actual)

    return {
        "status": "pass" if ok else "fail",
        "elapsed_ms": elapsed,
        "input": preview(plain(case.args)),
        "expected": preview(plain(case.expect)),
        "actual": shown,
        "note": note,
    }


def run_class_case(problem: Any, module: Any, case: T) -> dict:
    """Drive a sequence of operations against a designed class."""
    cls = getattr(module, problem.entry)
    expects = list(case.expect or [])
    results: list[Any] = []
    actuals: list[Any] = []
    started = time.perf_counter()
    instance = None
    failure: dict | None = None

    for index, op in enumerate(case.ops):
        name, raw_args = op[0], op[1] if len(op) > 1 else []
        args = materialize(list(raw_args), results)
        if index == 0:
            instance = cls(*args)
            returned = None
        else:
            returned = getattr(instance, name)(*args)
        results.append(returned)

        expect = expects[index] if index < len(expects) else ANY
        if isinstance(expect, _Any):
            actuals.append(None)
            continue

        actual = normalize(returned, expect)
        actuals.append(actual)
        one = T(args=case.args, expect=plain(expect))
        ok, note = compare(problem.compare, actual, one, args)
        if not ok and failure is None:
            failure = {
                "op": f"{name}({', '.join(preview(plain(a)) for a in raw_args)})",
                "op_index": index,
                "expected": preview(plain(expect)),
                "actual": preview(actual),
                "note": note,
            }

    elapsed = (time.perf_counter() - started) * 1000
    calls = ", ".join(
        f"{op[0]}({', '.join(preview(plain(a), 40) for a in (op[1] if len(op) > 1 else []))})"
        for op in case.ops
    )
    report = {
        "status": "fail" if failure else "pass",
        "elapsed_ms": elapsed,
        "input": preview(calls, 400),
        "expected": preview([plain(e) for e in expects]),
        "actual": preview(actuals),
        "note": "",
    }
    if failure:
        report.update(
            {
                "expected": failure["expected"],
                "actual": failure["actual"],
                "note": f"op #{failure['op_index']} {failure['op']} — {failure['note']}",
            }
        )
    return report


def run_case(problem: Any, module: Any, case: T) -> dict:
    """Execute one case, capturing stdout and turning exceptions into results."""
    buffer = io.StringIO()
    try:
        with contextlib.redirect_stdout(buffer):
            if problem.is_class:
                report = run_class_case(problem, module, case)
            else:
                fn = getattr(module, problem.entry, None)
                if fn is None:
                    raise AttributeError(
                        f"your solution has no function named {problem.entry!r}"
                    )
                report = run_function_case(problem, fn, case)
    except RecursionError as exc:
        report = _error_report(problem, case, "recursion limit exceeded — check your base case")
    except BaseException as exc:  # noqa: BLE001 - report anything the solution raises
        report = _error_report(problem, case, _format_error(exc))
    report["stdout"] = buffer.getvalue()[:2000]
    return report


def _error_report(problem: Any, case: T, message: str) -> dict:
    return {
        "status": "error",
        "elapsed_ms": 0.0,
        "input": preview(plain(case.args)) if not case.ops else preview("<operations>"),
        "expected": preview(plain(case.expect)),
        "actual": "—",
        "note": message,
    }


def main() -> None:
    payload = json.loads(sys.stdin.read())
    problem = get_problem(payload["slug"])
    report_path = payload["report_path"]
    timeout = payload.get("timeout_ms", 5000) / 1000
    indices = payload.get("indices") or list(range(len(problem.tests)))

    results: list[dict] = []

    def flush() -> None:
        with open(report_path, "w", encoding="utf-8") as handle:
            json.dump({"results": results}, handle)

    try:
        module = load_solution(payload["solution"])
    except BaseException as exc:  # noqa: BLE001 - syntax errors land here
        results.append(
            {
                "status": "error",
                "elapsed_ms": 0.0,
                "input": "—",
                "expected": "—",
                "actual": "—",
                "note": f"could not load your solution — {_format_error(exc)}",
                "stdout": "",
                "index": indices[0] if indices else 0,
                "fatal": True,
            }
        )
        flush()
        return

    sys.setrecursionlimit(RECURSION_LIMIT)
    threading.stack_size(STACK_BYTES)

    for index in indices:
        case = problem.tests[index]
        holder: dict[str, Any] = {}

        def work() -> None:
            holder["report"] = run_case(problem, module, case)

        thread = threading.Thread(target=work, daemon=True)
        thread.start()
        thread.join(timeout)

        if thread.is_alive():
            results.append(
                {
                    "status": "timeout",
                    "elapsed_ms": timeout * 1000,
                    "input": preview(plain(case.args)) if not case.ops else "<operations>",
                    "expected": preview(plain(case.expect)),
                    "actual": "—",
                    "note": f"still running after {timeout:.1f}s — likely too slow or an infinite loop",
                    "stdout": "",
                    "index": index,
                }
            )
            flush()
            # the hung thread cannot be joined, so leave immediately
            sys.stdout.flush()
            sys.stderr.flush()
            os._exit(0)

        report = holder["report"]
        report["index"] = index
        results.append(report)

    flush()


if __name__ == "__main__":  # pragma: no cover
    main()

