"""Parent side of the test harness: launch the child, collect its report."""

from __future__ import annotations

import json
import subprocess
import sys
import tempfile
from dataclasses import dataclass, field
from pathlib import Path

from .models import Problem

DEFAULT_TIMEOUT_MS = 5000


@dataclass
class CaseResult:
    index: int
    status: str  # pass | fail | error | timeout | skipped
    elapsed_ms: float = 0.0
    input: str = ""
    expected: str = ""
    actual: str = ""
    note: str = ""
    stdout: str = ""
    hidden: bool = False
    fatal: bool = False

    @property
    def ok(self) -> bool:
        return self.status == "pass"


@dataclass
class RunResult:
    problem: Problem
    cases: list[CaseResult] = field(default_factory=list)
    crashed: bool = False
    crash_note: str = ""

    @property
    def passed(self) -> int:
        return sum(1 for c in self.cases if c.ok)

    @property
    def total(self) -> int:
        return len(self.cases)

    @property
    def all_passed(self) -> bool:
        return self.total > 0 and self.passed == self.total and not self.crashed

    @property
    def first_failure(self) -> CaseResult | None:
        return next((c for c in self.cases if not c.ok), None)

    @property
    def slowest_ms(self) -> float:
        return max((c.elapsed_ms for c in self.cases), default=0.0)

    @property
    def total_ms(self) -> float:
        return sum(c.elapsed_ms for c in self.cases)


def run_tests(
    problem: Problem,
    solution: Path,
    indices: list[int] | None = None,
    timeout_ms: int = DEFAULT_TIMEOUT_MS,
) -> RunResult:
    """Run ``problem``'s tests against ``solution`` in a child process."""
    selected = indices if indices is not None else list(range(len(problem.tests)))
    result = RunResult(problem=problem)
    if not selected:
        return result

    with tempfile.TemporaryDirectory(prefix="dsa-run-") as tmp:
        report_path = Path(tmp) / "report.json"
        payload = {
            "slug": problem.slug,
            "solution": str(solution),
            "indices": selected,
            "timeout_ms": timeout_ms,
            "report_path": str(report_path),
        }
        # a generous ceiling: the child enforces the real per-case timeout
        wall = (timeout_ms / 1000) * len(selected) + 20
        try:
            completed = subprocess.run(
                [sys.executable, "-m", "dsa.child"],
                input=json.dumps(payload),
                capture_output=True,
                text=True,
                timeout=wall,
            )
            stderr = completed.stderr
        except subprocess.TimeoutExpired:
            result.crashed = True
            result.crash_note = f"the test process did not finish within {wall:.0f}s"
            return result

        if not report_path.exists():
            result.crashed = True
            result.crash_note = (
                stderr.strip().splitlines()[-1]
                if stderr.strip()
                else "the test process exited without reporting (a hard crash?)"
            )
            return result

        report = json.loads(report_path.read_text(encoding="utf-8"))

    for raw in report.get("results", []):
        index = raw.get("index", 0)
        result.cases.append(
            CaseResult(
                index=index,
                status=raw.get("status", "error"),
                elapsed_ms=float(raw.get("elapsed_ms") or 0.0),
                input=raw.get("input", ""),
                expected=raw.get("expected", ""),
                actual=raw.get("actual", ""),
                note=raw.get("note", ""),
                stdout=raw.get("stdout", ""),
                hidden=problem.tests[index].hidden if index < len(problem.tests) else False,
                fatal=bool(raw.get("fatal")),
            )
        )

    reported = {c.index for c in result.cases}
    for index in selected:
        if index not in reported:
            result.cases.append(
                CaseResult(
                    index=index,
                    status="skipped",
                    note="not reached (an earlier case stopped the run)",
                    hidden=problem.tests[index].hidden,
                )
            )
    result.cases.sort(key=lambda c: c.index)
    return result


def run_reference(problem: Problem, timeout_ms: int = DEFAULT_TIMEOUT_MS) -> RunResult:
    """Run a problem's own reference solution against its tests (dataset check)."""
    with tempfile.TemporaryDirectory(prefix="dsa-ref-") as tmp:
        path = Path(tmp) / f"{problem.slug.replace('-', '_')}.py"
        path.write_text(
            "from typing import Any, Dict, List, Optional, Set, Tuple\n"
            "from dsa.structures import GraphNode, ListNode, RandomNode, TreeNode\n\n"
            + problem.solution
            + "\n",
            encoding="utf-8",
        )
        return run_tests(problem, path, timeout_ms=timeout_ms)
